  const table = {};
  for (const [step, css] of Object.entries(CYAN)) {
    const solid = resolve(css);
    for (const a of [0.7, 0.75, 0.85, 1]) {
      const key = `cyan-${step}${a===1?'':'/'+Math.round(a*100)}`;
      table[key] = {};
