      const cs = getComputedStyle(el);
      if (cs.visibility === 'hidden' || cs.display === 'none' || Number(cs.opacity) === 0) continue;
      if (el.getBoundingClientRect().width === 0) continue;
      const size = Number.parseFloat(cs.fontSize);
      const weight = Number(cs.fontWeight) || 400;
      const large = size >= 24 || (size >= 18.66 && weight >= 700);
      const need = large ? 3 : 4.5;
      const bg = effBg(el);
      const fg = px(cs.color, hex(bg));
      const r = ratio(fg, bg);
      if (r < need) bad.push({ tag: el.tagName, cls: el.className?.toString?.().slice(0,70), size: cs.fontSize, fg: hex(fg), bg: hex(bg), ratio: r, need, text: (el.textContent||'').trim().slice(0,45) });
    }
    return bad;
  };

  const out = {};
  for (const t of ['light','dark']) {
    [...document.querySelectorAll('[role="radiogroup"] input')].find(i=>i.value===t).click();
    document.activeElement.blur();
    await wait(400);
    out[t] = scan();
  }
  return { lightFailures: out.light.length, darkFailures: out.dark.length, light: out.light, dark: out.dark };
}

async () => {
  const wait=(ms)=>new Promise(r=>setTimeout(r,ms));
  const cv=document.createElement('canvas');cv.width=1;cv.height=1;
  const ctx=cv.getContext('2d',{willReadFrequently:true});
  const hex=(a)=>'#'+a.map(n=>Math.round(n).toString(16).padStart(2,'0')).join('');
  const paint=(layers)=>{ // layers: bottom-first list of css colours
    ctx.clearRect(0,0,1,1);
    for(const c of layers){ ctx.fillStyle=c; ctx.fillRect(0,0,1,1); }
    const d=ctx.getImageData(0,0,1,1).data; return [d[0],d[1],d[2]];
  };
  const srgb=(c)=>{c/=255;return c<=0.03928?c/12.92:Math.pow((c+0.055)/1.055,2.4);};
  const lum=([r,g,b])=>0.2126*srgb(r)+0.7152*srgb(g)+0.0722*srgb(b);
  const ratio=(a,b)=>{const l1=lum(a),l2=lum(b);return Math.round(((Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05))*100)/100;};

  // Collect every background layer from the element up to <html>, then paint
  // them bottom-first so translucent panels sit on what is actually below.
  const effBg=(el)=>{
    const layers=[];
    let n=el;
    while(n){ const b=getComputedStyle(n).backgroundColor;
      if(b && b!=='rgba(0, 0, 0, 0)' && b!=='transparent') layers.unshift(b);
      n=n.parentElement; }
    layers.unshift(getComputedStyle(document.documentElement).backgroundColor==='rgba(0, 0, 0, 0)' ? (document.documentElement.classList.contains('dark')?'#0a0a0a':'#ffffff') : getComputedStyle(document.documentElement).backgroundColor);
    return paint(layers);
  };

  const scan=()=>{
    const bad=[];
    for(const el of document.querySelectorAll('body *')){
      if(el.closest('[aria-hidden="true"]')) continue;
      const own=[...el.childNodes].some(n=>n.nodeType===3&&n.textContent.trim().length>1);
      if(!own) continue;
      const cs=getComputedStyle(el);
      if(cs.visibility==='hidden'||cs.display==='none'||Number(cs.opacity)===0) continue;
      if(el.getBoundingClientRect().width===0) continue;
      const size=Number.parseFloat(cs.fontSize), weight=Number(cs.fontWeight)||400;
      const need=(size>=24||(size>=18.66&&weight>=700))?3:4.5;
      const bg=effBg(el);
      const fg=paint([hex(bg), cs.color]);
      const r=ratio(fg,bg);
      if(r<need) bad.push({ cls:(el.className?.toString?.()||'').slice(0,60), size:cs.fontSize, fg:hex(fg), bg:hex(bg), ratio:r, need, text:(el.textContent||'').trim().slice(0,40) });
    }
    return bad;
  };

  const out={};
  for(const t of ['light','dark']){
    [...document.querySelectorAll('[role="radiogroup"] input')].find(i=>i.value===t).click();
    document.activeElement.blur();
    await wait(400);
    out[t]=scan();
  }
  const summarise=(list)=>{ const m={}; for(const f of list){ const k=f.cls.split(' ').filter(c=>/text-|decoration/.test(c)).join(' ')||f.cls; (m[k]??=[]).push(f.ratio); } return Object.entries(m).map(([k,v])=>({ style:k, count:v.length, worst:Math.min(...v) })).sort((a,b)=>a.worst-b.worst); };
  return { lightCount: out.light.length, darkCount: out.dark.length, lightGroups: summarise(out.light), darkGroups: summarise(out.dark) };
}
